cd /workspaces/semio && python3 -c "
import json
a = json.load(open('/tmp/applied_inverse.json'))
b = json.load(open('/tmp/expected_original.json'))

# Compare all top-level fields first  
for k in set(list(a.keys()) + list(b.keys())):
    if k in ('types', 'designs', 'tags', 'folders', 'ports', 'concepts', 'files', 'authors', 'attributes', 'qualities'):
        continue
    if a.get(k) != b.get(k):
        print(f'Kit.{k}: {str(a.get(k))[:60]} != {str(b.get(k))[:60]}')

# Compare collection counts
for k in ('types', 'designs', 'tags', 'folders', 'ports', 'concepts', 'files', 'authors', 'attributes', 'qualities'):
    al = a.get(k, []) or []
    bl = b.get(k, []) or []
    if len(al) != len(bl):
        print(f'Kit.{k}: count {len(al)} != {len(bl)}')

# Now compare designs by GUID for each matched pair
for ad in a.get('designs', []):
    bd = next((d for d in b.get('designs', []) if d['guid'] == ad['guid']), None)
    if not bd:
        print(f'Design {ad[\"guid\"]} not found in expected')
        continue
    for k in set(list(ad.keys()) + list(bd.keys())):
        if k in ('pieces', 'connections', 'attributes', 'concepts', 'authors'):
            continue
        if ad.get(k) != bd.get(k):
            print(f'Design[{ad[\"guid\"][:8]}].{k}: {str(ad.get(k))[:60]} != {str(bd.get(k))[:60]}')
    # Compare connections
    diffs = 0
    for ac in ad.get('connections', []):
        bc = next((c for c in bd.get('connections', []) if c['guid'] == ac['guid']), None)
        if not bc: continue
        for ck in set(list(ac.keys()) + list(bc.keys())):
            if ac.get(ck) != bc.get(ck):
                if diffs < 5:
                    print(f'Connection[{ac[\"guid\"][:8]}].{ck}: {str(ac.get(ck))[:60]} != {str(bc.get(ck))[:60]}')
                diffs += 1
    if diffs > 5:
        print(f'... and {diffs-5} more connection field differences')
" 2>&1

