    expected = json.load(f)

def compare_by_guid(name, applied_list, expected_list, depth=0):
    """Compare lists by GUID matching"""
    applied_by_guid = {item.get('guid', item.get('name', str(i))): item for i, item in enumerate(applied_list)}
    expected_by_guid = {item.get('guid', item.get('name', str(i))): item for i, item in enumerate(expected_list)}

    diffs = []
    for guid in set(list(applied_by_guid.keys()) + list(expected_by_guid.keys())):
        if guid not in applied_by_guid:
            diffs.append(f"  Missing in applied: guid={guid}")
        elif guid not in expected_by_guid:
            diffs.append(f"  Extra in applied: guid={guid}")
        else:
            a = applied_by_guid[guid]
            e = expected_by_guid[guid]
            for k in set(list(a.keys()) + list(e.keys())):
                if k not in a:
                    diffs.append(f"  [{guid[:8]}] Missing field: {k}")
                elif k not in e:
                    diffs.append(f"  [{guid[:8]}] Extra field: {k}")
                elif a[k] != e[k]:
                    if isinstance(a[k], (int, float, str, bool, type(None))):
                        diffs.append(f"  [{guid[:8]}].{k}: {repr(a[k])} != {repr(e[k])}")
                    elif isinstance(a[k], list):
                        diffs.append(f"  [{guid[:8]}].{k}: lists differ (a={len(a[k])}, e={len(e[k])})")
                    elif isinstance(a[k], dict):
                        for dk in set(list(a[k].keys()) + list(e[k].keys())):
                            if dk not in a[k]:
                                diffs.append(f"  [{guid[:8]}].{k}.{dk}: missing in applied")
                            elif dk not in e[k]:
                                diffs.append(f"  [{guid[:8]}].{k}.{dk}: extra in applied")
                            elif a[k][dk] != e[k][dk]:
                                diffs.append(f"  [{guid[:8]}].{k}.{dk}: {repr(a[k][dk])} != {repr(e[k][dk])}")
    return diffs

for field in ['types', 'designs', 'tags', 'ports', 'files', 'concepts']:
    diffs = compare_by_guid(field, applied[field], expected[field])
    if diffs:
        print(f"\n=== {field} ===")
        for d in diffs[:30]:  # limit output
            print(d)
        if len(diffs) > 30:
            print(f"  ... and {len(diffs)-30} more diffs")
