import json

with open('/tmp/applied_inverse.json') as f:
    applied = json.load(f)
with open('/tmp/expected_original.json') as f:
    expected = json.load(f)

TOLERANCE = 1e-5

def float_eq(a, b):
    if a is None and b is None: return True
    if a is None or b is None: return False
    return abs(a - b) < TOLERANCE

def by_guid(lst):
    return {item['guid']: item for item in lst}

a_types = by_guid(applied['types'])
e_types = by_guid(expected['types'])

# Check each type
diffs = []
for guid, e_t in e_types.items():
    a_t = a_types.get(guid)
    if a_t is None:
        diffs.append(f"Missing type: {guid[:8]} ({e_t.get('name')})")
        continue

    # Compare scalar fields
    for k in ['name', 'description', 'icon', 'image', 'folder', 'unit', 'stock', 'isAbstract', 'virtual']:
        if a_t.get(k) != e_t.get(k):
            diffs.append(f"[{guid[:8]}].{k}: {repr(a_t.get(k))} != {repr(e_t.get(k))}")

    # Compare parent
    a_parent = a_t.get('parent', {}) or {}
    e_parent = e_t.get('parent', {}) or {}
    if a_parent.get('guid') != e_parent.get('guid'):
        diffs.append(f"[{guid[:8]}].parent.guid: {a_parent.get('guid')} != {e_parent.get('guid')}")

    # Compare location
    a_loc = a_t.get('location', {}) or {}
    e_loc = e_t.get('location', {}) or {}
    if a_loc.get('guid') != e_loc.get('guid'):
        diffs.append(f"[{guid[:8]}].location.guid: {a_loc.get('guid')} != {e_loc.get('guid')}")

    # Compare concepts
    a_concepts = sorted([c.get('guid','') for c in a_t.get('concepts', []) or []])
    e_concepts = sorted([c.get('guid','') for c in e_t.get('concepts', []) or []])
    if a_concepts != e_concepts:
        diffs.append(f"[{guid[:8]}].concepts: {len(a_concepts)} != {len(e_concepts)}")

    # Compare authors
    a_authors = sorted([c.get('guid','') for c in a_t.get('authors', []) or []])
    e_authors = sorted([c.get('guid','') for c in e_t.get('authors', []) or []])
    if a_authors != e_authors:
        diffs.append(f"[{guid[:8]}].authors: {a_authors} != {e_authors}")

    # Compare connectors
    a_conns = by_guid(a_t.get('connectors', []) or [])
    e_conns = by_guid(e_t.get('connectors', []) or [])
    if len(a_conns) != len(e_conns):
        diffs.append(f"[{guid[:8]}].connectors: len {len(a_conns)} != {len(e_conns)}")
    else:
        for cg, ec in e_conns.items():
            ac = a_conns.get(cg)
            if ac is None:
                diffs.append(f"[{guid[:8]}].connectors[{cg[:8]}]: missing")
                continue
            for ck in ['name', 'mandatory']:
                if ac.get(ck) != ec.get(ck):
                    diffs.append(f"[{guid[:8]}].connectors[{cg[:8]}].{ck}: {repr(ac.get(ck))} != {repr(ec.get(ck))}")
            # port
            a_port = (ac.get('port') or {})
            e_port = (ec.get('port') or {})
            if a_port.get('guid') != e_port.get('guid'):
                diffs.append(f"[{guid[:8]}].connectors[{cg[:8]}].port.guid: {a_port.get('guid')} != {e_port.get('guid')}")
            # T
            if 't' in ac and 't' in ec:
                if not float_eq(ac['t'], ec['t']):
                    diffs.append(f"[{guid[:8]}].connectors[{cg[:8]}].t: {ac['t']} != {ec['t']}")
            # point/direction - use tolerance
            for vec_name in ['point', 'direction']:
                av = ac.get(vec_name, {}) or {}
                ev = ec.get(vec_name, {}) or {}
                for comp in ['x', 'y', 'z']:
                    if not float_eq(av.get(comp, 0), ev.get(comp, 0)):
                        diffs.append(f"[{guid[:8]}].connectors[{cg[:8]}].{vec_name}.{comp}: {av.get(comp)} != {ev.get(comp)}")
            # props
            a_props = by_guid(ac.get('props', []) or [])
            e_props = by_guid(ec.get('props', []) or [])
            if len(a_props) != len(e_props):
                diffs.append(f"[{guid[:8]}].connectors[{cg[:8]}].props: {len(a_props)} != {len(e_props)}")
            # attributes
            a_attrs = by_guid(ac.get('attributes', []) or [])
            e_attrs = by_guid(ec.get('attributes', []) or [])
            if len(a_attrs) != len(e_attrs):
                diffs.append(f"[{guid[:8]}].connectors[{cg[:8]}].attributes: {len(a_attrs)} != {len(e_attrs)}")

    # Compare models
    a_models = by_guid(a_t.get('models', []) or [])
    e_models = by_guid(e_t.get('models', []) or [])
    if len(a_models) != len(e_models):
        diffs.append(f"[{guid[:8]}].models: len {len(a_models)} != {len(e_models)}")
    else:
        for mg, em in e_models.items():
            am = a_models.get(mg)
            if am is None:
                diffs.append(f"[{guid[:8]}].models[{mg[:8]}]: missing")
                continue
            if am.get('name') != em.get('name'):
                diffs.append(f"[{guid[:8]}].models[{mg[:8]}].name: {repr(am.get('name'))} != {repr(em.get('name'))}")
            a_file = (am.get('file') or {})
            e_file = (em.get('file') or {})
            if a_file.get('guid') != e_file.get('guid'):
                diffs.append(f"[{guid[:8]}].models[{mg[:8]}].file.guid: {a_file.get('guid')} != {e_file.get('guid')}")
            a_tags = sorted([t.get('guid','') for t in am.get('tags', []) or []])
            e_tags = sorted([t.get('guid','') for t in em.get('tags', []) or []])
            if a_tags != e_tags:
                diffs.append(f"[{guid[:8]}].models[{mg[:8]}].tags: {a_tags} != {e_tags}")
            a_attrs = by_guid(am.get('attributes', []) or [])
            e_attrs = by_guid(em.get('attributes', []) or [])
            if len(a_attrs) != len(e_attrs):
                diffs.append(f"[{guid[:8]}].models[{mg[:8]}].attrs: {len(a_attrs)} != {len(e_attrs)}")

    # Compare props
    a_props = by_guid(a_t.get('props', []) or [])
    e_props = by_guid(e_t.get('props', []) or [])
    if len(a_props) != len(e_props):
        diffs.append(f"[{guid[:8]}].props: len {len(a_props)} != {len(e_props)}")
    else:
        for pg, ep in e_props.items():
            ap = a_props.get(pg)
            if ap is None:
                diffs.append(f"[{guid[:8]}].props[{pg[:8]}]: missing")
            else:
                for pk in ['value', 'unit']:
                    if ap.get(pk) != ep.get(pk):
                        diffs.append(f"[{guid[:8]}].props[{pg[:8]}].{pk}: {repr(ap.get(pk))} != {repr(ep.get(pk))}")
                a_qual = (ap.get('quality') or {})
                e_qual = (ep.get('quality') or {})
                if a_qual.get('guid') != e_qual.get('guid'):
                    diffs.append(f"[{guid[:8]}].props[{pg[:8]}].quality.guid: {a_qual.get('guid')} != {e_qual.get('guid')}")

    # Compare attributes
    a_attrs = by_guid(a_t.get('attributes', []) or [])
    e_attrs = by_guid(e_t.get('attributes', []) or [])
    if len(a_attrs) != len(e_attrs):
        diffs.append(f"[{guid[:8]}].attributes: len {len(a_attrs)} != {len(e_attrs)}")
    else:
        for ag, ea in e_attrs.items():
            aa = a_attrs.get(ag)
            if aa is None:
                diffs.append(f"[{guid[:8]}].attributes[{ag[:8]}]: missing")
            else:
                for ak in ['key', 'value', 'definition']:
                    if (aa.get(ak) or None) != (ea.get(ak) or None):
                        diffs.append(f"[{guid[:8]}].attributes[{ag[:8]}].{ak}: {repr(aa.get(ak))} != {repr(ea.get(ak))}")

for d in diffs[:50]:
